def _load_video_with_opencv(media_path):
    """Load video frames without requiring diffusers' imageio backend."""
    import cv2

    capture = cv2.VideoCapture(media_path)
    if not capture.isOpened():
        raise RuntimeError(f"Could not open video: {media_path}")
    fps = float(capture.get(cv2.CAP_PROP_FPS))
    frames = []
    while True:
        ok, frame = capture.read()
        if not ok:
            break
        frames.append(Image.fromarray(cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)))
    capture.release()
    if not frames:
        raise RuntimeError(f"Could not decode video frames: {media_path}")
    return frames, fps if fps > 0 else 8.0

