def solid_mpm_mask(batch, batch_size=None, device=None):
    """Return the samples that carry real solid-MPM deformation semantics."""
    if batch_size is None:
        batch_size = batch['points_tgt'].shape[0]
    if device is None:
        device = batch['points_tgt'].device

    mask = torch.ones(batch_size, dtype=torch.bool, device=device)
    if 'is_mpm' in batch:
        mask &= batch['is_mpm'].to(device=device, dtype=torch.bool).reshape(-1)
    if 'mat_type' in batch:
        material_type = batch['mat_type'].to(device=device).reshape(-1)
        mask &= material_type.ne(4)
    return mask
